    private static func testAlertTones(in directory: URL, recorder: inout Recorder) throws {
        let decoder = JSONDecoder()
        let legacy = try decoder.decode(Preferences.self, from: Data("{}".utf8))
        recorder.check(legacy.timerTone == .stillChime && legacy.inactivityTone == .tink,
                       "sounds: an existing setup keeps its original timer and inactivity cues")
        let unknown = try decoder.decode(Preferences.self, from:
            Data(#"{"timerTone":"removed","inactivityTone":"glass","soundEnabled":false}"#.utf8))
        recorder.check(unknown.timerTone == .stillChime && unknown.inactivityTone == .glass && !unknown.soundEnabled,
                       "sounds: an unknown tone preserves the other sound and mute setting")
        for tone in AlertTone.allCases {
            recorder.check((tone.loadSound()?.duration ?? 0) > 0, "sounds: can load " + tone.displayName)
        }
        recorder.check(AlertTone.timerChoices.allSatisfy { $0.notificationSound != nil },
                       "sounds: every timer choice can be scheduled in a notification")

        var played: [AlertTone] = []
        let model = AppModel(dataDirectory: directory, syncJournalOnLaunch: false, playTone: { played.append($0) })
        model.preferences.notificationsEnabled = false
        model.preferences.inactivityTone = .wood
        model.startFocus(minutes: 1)
        model.preferences.timerTone = .feltPiano
        model.savePreferences()
        guard let focusDeadline = model.timer.deadline else { recorder.fail("sounds: focus did not start"); return }
        model.advance(to: focusDeadline)
        model.advance(to: focusDeadline.addingTimeInterval(1))
        recorder.check(played == [.feltPiano], "sounds: a running focus uses the latest choice exactly once")
        model.startBreak(.shortBreak)
        guard let breakDeadline = model.timer.deadline else { recorder.fail("sounds: break did not start"); return }
        model.advance(to: breakDeadline)
        recorder.check(played == [.feltPiano, .feltPiano], "sounds: a break ends with the selected timer tone")
        let restored = AppModel(dataDirectory: directory, syncJournalOnLaunch: false)
        recorder.check(restored.preferences.timerTone == .feltPiano && restored.preferences.inactivityTone == .wood,
                       "sounds: timer and inactivity choices restore independently")
    }

    private static func testFocusShortcuts(recorder: inout Recorder) {
        var opens = [Date?]()
        var ends = 0
        var lifecycle = FocusShortcutLifecycle(runOpen: { opens.append($0); return true }, runEnd: { ends += 1; return true })
        let now = Date(timeIntervalSince1970: 1_800_000_000)
        let ready = TimerState(mode: .focus, duration: 60)
        lifecycle.opened(with: ready)
        var running = ready
        running.start(at: now)
        lifecycle.timerChanged(from: ready, to: running)
        lifecycle.timerChanged(from: running, to: running)
        recorder.check(opens == [nil, now.addingTimeInterval(60)] && ends == 0,
                       "Focus shortcuts: open immediately, then set the real deadline exactly once")
        var paused = running
        paused.pause(at: now.addingTimeInterval(10))
        lifecycle.timerChanged(from: running, to: paused)
        var resumed = paused
        resumed.start(at: now.addingTimeInterval(30))
        lifecycle.timerChanged(from: paused, to: resumed)
        recorder.check(opens == [nil, running.deadline, nil, now.addingTimeInterval(80)] && ends == 0,
                       "Focus shortcuts: pause removes the expiry and resume sends the revised deadline")
        var completed = resumed
        _ = completed.tick(at: now.addingTimeInterval(80))
        lifecycle.timerChanged(from: resumed, to: completed)
        lifecycle.timerChanged(from: completed, to: completed)
        recorder.check(ends == 1, "Focus shortcuts: completing the countdown ends system Focus once")
        var rest = TimerState(mode: .shortBreak, duration: 60)
        rest.start(at: now)
        lifecycle.timerChanged(from: completed, to: rest)
        recorder.check(opens.count == 4 && ends == 1, "Focus shortcuts: breaks leave the system Focus alone")
        lifecycle.timerChanged(from: ready, to: running)
        lifecycle.timerChanged(from: running, to: ready)
        recorder.check(ends == 2, "Focus shortcuts: cancelling the active session ends the system Focus")
    }

    private static func testStayAwake(in directory: URL, recorder: inout Recorder) {
        let fileManager = FileManager.default
        try? fileManager.createDirectory(at: directory, withIntermediateDirectories: true)
        let log = directory.appendingPathComponent("pmset.log")
        let fake = directory.appendingPathComponent("pmset")
        let battery = directory.appendingPathComponent("battery")
        try? "Now drawing from 'AC Power'\n -InternalBattery-0\t80%; charging; present: true\n".write(to: battery, atomically: true, encoding: .utf8)
        try? "#!/bin/sh\nif [ \"$1\" = -g ]; then cat '\(battery.path)'; else echo \"$*\" >> '\(log.path)'; fi\n"
            .write(to: fake, atomically: true, encoding: .utf8)
        try? fileManager.setAttributes([.posixPermissions: 0o755], ofItemAtPath: fake.path)

        func run(token: URL, contents: String, until stop: () -> Void, _ name: String) {
            try? fileManager.removeItem(at: log)
            try? contents.write(to: token, atomically: true, encoding: .utf8)
            guard let script = StayAwake.helperScript(token: token.path, pid: ProcessInfo.processInfo.processIdentifier,
                                                      pmset: fake.path, interval: 1) else {
                recorder.fail("stay awake: \(name) helper script is unavailable"); return
            }
            let process = Process()
            process.executableURL = URL(fileURLWithPath: "/bin/sh")
            process.arguments = ["-c", script]
            let output = Pipe()
            process.standardOutput = output
            do { try process.run() } catch { recorder.fail("stay awake: \(name) could not start"); return }
            process.waitUntilExit()
            let pidText = String(decoding: output.fileHandleForReading.readDataToEndOfFile(), as: UTF8.self)
            let pid = pid_t(pidText.trimmingCharacters(in: .whitespacesAndNewlines))
            recorder.check(pid != nil, "stay awake: \(name) reports the watcher pid")
            recorder.check(waitUntil(timeout: 1) { (try? String(contentsOf: log, encoding: .utf8)) == "-a disablesleep 1\n" },
                           "stay awake: \(name) disables sleep first")
            recorder.check(pid.map { kill($0, 0) == 0 } ?? false, "stay awake: \(name) watcher keeps running")
            stop()
            recorder.check(waitUntil(timeout: 5) { (try? String(contentsOf: log, encoding: .utf8)) == "-a disablesleep 1\n-a disablesleep 0\n" },
                           "stay awake: \(name) restores sleep")
            recorder.check(!fileManager.fileExists(atPath: token.path), "stay awake: \(name) removes the token")
        }

        let token = directory.appendingPathComponent("stay-awake.token")
        run(token: token, contents: "0\n", until: { try? fileManager.removeItem(at: token) }, "turned off")
        run(token: token, contents: "\(Int(Date().timeIntervalSince1970) + 2)\n", until: {}, "deadline")
        run(token: token, contents: "0\n", until: {
            try? "Now drawing from 'Battery Power'\n -InternalBattery-0\t8%; discharging; present: true\n"
                .write(to: battery, atomically: true, encoding: .utf8)
        }, "low battery")
        recorder.check(StayAwake.helperScript(token: "/tmp/it's", pid: 1) == nil, "stay awake: rejects quotes in the token path")

        let model = AppModel(dataDirectory: directory.appendingPathComponent("model", isDirectory: true), syncJournalOnLaunch: false)
        model.preferences.stayAwakeLidClosed = false
        model.startStayAwake(minutes: 120)
        recorder.check(model.stayAwake.isActive, "stay awake: starts")
        model.stayAwake.refresh(now: Date().addingTimeInterval(121 * 60))
        recorder.check(!model.stayAwake.isActive, "stay awake: ends after its duration")
        model.startStayAwake(minutes: nil)
        model.stayAwake.refresh(now: Date().addingTimeInterval(365 * 86_400))
        recorder.check(model.stayAwake.isActive, "stay awake: until turned off keeps going")
        model.stayAwake.stop()
        recorder.check(!model.stayAwake.isActive, "stay awake: stops")

        let decoded = try? JSONDecoder().decode(Preferences.self, from: Data(#"{"stayAwakeMinutes": 5000}"#.utf8))
        recorder.check(decoded?.stayAwakeMinutes == 1440 && decoded?.stayAwakeLidClosed == true,
                       "stay awake: preferences clamp and default to lid-closed mode")
    }

    private static func testRestReminder(in directory: URL, recorder: inout Recorder) {
        var calendar = Calendar(identifier: .gregorian)
        calendar.timeZone = .current
        func date(_ day: Int, _ hour: Int, _ minute: Int) -> Date {
            calendar.date(from: DateComponents(year: 2026, month: 9, day: day, hour: hour, minute: minute))!
        }
        recorder.check(!RestSchedule.contains(date(18, 21, 59), startMinute: 22 * 60, endMinute: 7 * 60, calendar: calendar),
                       "rest window: inactive before an overnight start")
