                       "rest window: active at start")
        recorder.check(RestSchedule.contains(date(19, 0, 0), startMinute: 22 * 60, endMinute: 7 * 60, calendar: calendar),
                       "rest window: active across midnight")
        recorder.check(!RestSchedule.contains(date(19, 7, 0), startMinute: 22 * 60, endMinute: 7 * 60, calendar: calendar),
                       "rest window: inactive at end")
        recorder.check(!RestSchedule.contains(date(19, 0, 0), startMinute: 0, endMinute: 0, calendar: calendar),
                       "rest window: matching start and end do not create an all-day alert")

        var bedtime = Preferences(restStartMinute: 45, restEndMinute: 480)
        let request = RestSchedule.notificationRequest(for: bedtime)
        let trigger = request?.trigger as? UNCalendarNotificationTrigger
        recorder.check(request?.identifier == "still.rest.start" && trigger?.repeats == true
                       && trigger?.dateComponents == DateComponents(hour: 0, minute: 45),
                       "bedtime: repeating local notification at 00:45")
        recorder.check(!RestSchedule.contains(date(19, 0, 44), startMinute: 45, endMinute: 480, calendar: calendar)
                       && RestSchedule.contains(date(19, 0, 45), startMinute: 45, endMinute: 480, calendar: calendar),
                       "bedtime: panel opens at the same minute as the notification")
        bedtime.restEndMinute = 45
        recorder.check(RestSchedule.notificationRequest(for: bedtime) == nil, "bedtime: equal times cancel notification")
        bedtime.restEndMinute = 480
        bedtime.restReminderEnabled = false
        recorder.check(RestSchedule.notificationRequest(for: bedtime) == nil, "bedtime: disabling cancels notification")

        let model = AppModel(dataDirectory: directory, preview: true)
        model.preferences.restStartMinute = 22 * 60
        model.preferences.restEndMinute = 7 * 60
        model.refreshClock(to: date(18, 23, 30))
        recorder.check(model.restReminderActive, "rest reminder: appears inside the configured window")
        model.snoozeRestReminder(at: date(18, 23, 30))
        recorder.check(!model.restReminderActive, "rest reminder: snooze hides the panel")
        model.refreshClock(to: date(18, 23, 34))
        recorder.check(!model.restReminderActive, "rest reminder: stays hidden before snooze ends")
        model.refreshClock(to: date(18, 23, 35))
        recorder.check(model.restReminderActive, "rest reminder: returns when snooze ends")
        model.refreshClock(to: date(19, 7, 0))
        recorder.check(!model.restReminderActive, "rest reminder: clears at the end of the window")

        do {
            let preferences = Preferences(restReminderEnabled: true, restStartMinute: 23 * 60 + 15,
                                          restEndMinute: 6 * 60 + 45, restMessage: "Rest tonight.")
            let restored = try JSONDecoder().decode(Preferences.self, from: JSONEncoder().encode(preferences))
            recorder.check(restored.restStartMinute == 23 * 60 + 15 && restored.restEndMinute == 6 * 60 + 45
                           && restored.restMessage == "Rest tonight.", "rest reminder: settings round trip")
        } catch { recorder.fail("rest reminder: settings round trip failed: \(error)") }
    }

    private static func testQuietClock(in directory: URL, recorder: inout Recorder) {
        let model = AppModel(dataDirectory: directory, preview: true)
        model.preferences.soundEnabled = false
        recorder.check(!model.shouldPlayDirectChime(for: .focus),
                       "quiet clock: muted focus completion does not request a direct chime")
        model.preferences.soundEnabled = true
        recorder.check(model.shouldPlayDirectChime(for: .focus),
                       "quiet clock: focus completion requests the bundled chime independent of notifications")
        recorder.check(!model.shouldPlayDirectChime(for: .shortBreak),
                       "quiet clock: breaks retain system-notification sound behavior")
        model.preferences.soundEnabled = false
        var updates = 0
        let observer = model.objectWillChange.sink { updates += 1 }
        defer { observer.cancel() }
        model.refreshClock(to: model.now.addingTimeInterval(0.25))
        recorder.check(updates == 0, "ready clock: no idle view invalidation")

        model.startFocus(minutes: 1)
        let start = model.now
        updates = 0
        for fraction in [0.25, 0.5, 0.75] { model.refreshClock(to: start.addingTimeInterval(fraction)) }
        recorder.check(updates == 0, "running clock: unchanged displayed second does not publish")
        model.refreshClock(to: start.addingTimeInterval(1))
        recorder.check(model.remaining == 59 && updates == 1, "running clock: one publication per displayed second")

        model.primaryAction()
        updates = 0
        model.refreshClock(to: model.now.addingTimeInterval(3))
        recorder.check(updates == 0, "paused clock: no idle view invalidation")
        model.primaryAction()
        let deadline = model.timer.deadline!
        model.refreshClock(to: deadline.addingTimeInterval(0.25))
        recorder.check(model.timer.phase == .completed && model.sessions.count == 1, "quiet clock: deadline still completes exactly once")
        updates = 0
        model.refreshClock(to: deadline.addingTimeInterval(10))
        recorder.check(updates == 0 && model.sessions.count == 1, "completed clock: no publication or duplicate session")
        model.refreshClock(to: Calendar.current.date(byAdding: .day, value: 1, to: model.now)!)
        recorder.check(updates == 1, "idle clock: daily statistics refresh at midnight")
    }

