    private static func testBackgroundJournalImportAndCompletion(in directory: URL, recorder: inout Recorder) {
        let stateDirectory = directory.appendingPathComponent("state", isDirectory: true)
        let journalURL = directory.appendingPathComponent("sessions.md")
        let imported = FocusSession(
            id: UUID(uuidString: "00000000-0000-0000-0000-000000000011")!,
            startedAt: Date(timeIntervalSince1970: 1_789_000_000),
            completedAt: Date(timeIntervalSince1970: 1_789_001_500),
            duration: 1_500
        )
        let baseline = Date(timeIntervalSince1970: floor(Date().timeIntervalSince1970) - 30)
        var timer = TimerState(mode: .focus, duration: 60)
        timer.start(at: baseline)

        var preferences = Preferences()
        preferences.soundEnabled = false
        preferences.notificationsEnabled = false
        preferences.journalPath = journalURL.path
        let archive = LocalArchive(timer: timer, sessions: [], preferences: preferences)

        do {
            try MarkdownJournal.synchronize(sessions: [imported], to: journalURL)
            try write(archive: archive, to: archiveURL(in: stateDirectory))

            let model = AppModel(dataDirectory: stateDirectory)
            model.advance(to: baseline.addingTimeInterval(61))
            recorder.check(waitForJournal(model), "journal worker: background import/sync reached idle state")

            let ids = Set(model.sessions.map(\.id))
            recorder.check(ids.contains(imported.id), "journal worker: existing Markdown session imports into cache")
            recorder.check(model.sessions.count == 2, "journal worker: completion during startup sync is retained")
            let journal = try MarkdownJournal.read(from: journalURL)
            recorder.check(journal.count == 2, "journal worker: Markdown receives imported and newly completed sessions")
            recorder.check(Set(journal.map(\.id)) == ids, "journal worker: journal and cache IDs agree")
        } catch {
            recorder.fail("journal worker: fixture failed: \(error)")
        }
    }

    private static func testDailyOverview(in directory: URL, recorder: inout Recorder) throws {
        let journal = directory.appendingPathComponent("plan.md")
        let state = directory.appendingPathComponent("state")
        let model = AppModel(dataDirectory: state, syncJournalOnLaunch: false)
        prepareForTimerUse(model, focusMinutes: 1)
        recorder.check(model.setJournalPath(journal.path), "daily: select shared journal")
        recorder.check(model.suggestedGoal == 2 && model.takeDailyGoalPrompt(), "daily: first open offers two sessions")
        let reopened = AppModel(dataDirectory: state, syncJournalOnLaunch: false)
        recorder.check(!reopened.takeDailyGoalPrompt(), "daily: dismissing the prompt survives relaunch")
        let midnight = Calendar.current.startOfDay(for: Date())
        let yesterday = midnight.addingTimeInterval(-60)
        model.setDailyGoal(3, at: yesterday)
        model.advance(to: Date())
        recorder.check(model.suggestedGoal == 3 && model.today.goal == nil, "daily: previous goal suggested but not committed")
        recorder.check(model.days[DailyEvent.dayID(for: yesterday)]?.status(isToday: false) == "3 short",
                       "daily: a planned day with zero completions remains in history")
        model.setDailyGoal(3)
        model.setDailyGoal(1)
        model.startFocus(minutes: 1)
        model.primaryAction() // Pause and resume the same interval.
        model.primaryAction()
        guard let deadline = model.timer.deadline else { recorder.fail("daily: no focus deadline"); return }
        model.advance(to: deadline)
        model.advance(to: deadline)
        let completionDay = DailyEvent.dayID(for: deadline)
        recorder.check(model.days[completionDay]?.completed == 1, "daily: resumed focus counts exactly once")
        model.startBreak(.shortBreak)
        if let end = model.timer.deadline { model.advance(to: end) }
        model.startFocus(minutes: 1)
        model.reset()
        model.reset()
        recorder.check(waitForJournal(model) && model.journalError == nil, "daily: background goal and timer writes finish")
        let records = try MarkdownJournal.readEntries(from: journal)
        recorder.check(records.sessions.count == 1 && records.events.count == 4,
                       "daily: three commitments, one early stop, one completion and no breaks")
        let fresh = AppModel(dataDirectory: directory.appendingPathComponent("second-mac"), syncJournalOnLaunch: false)
        recorder.check(fresh.setJournalPath(journal.path), "daily: import the shared journal alone")
        recorder.check(fresh.today.goal == 1 && !fresh.takeDailyGoalPrompt(), "daily: latest goal imports before the prompt")
        recorder.check(fresh.days[completionDay]?.completed == 1, "daily: imported completion does not double count")
        let copied = try String(contentsOf: journal, encoding: .utf8)
        recorder.check(copied.contains("Deep work goal") && copied.contains("stopped early"), "daily: readable Markdown commitments and stops")

        let broken = "<!-- still-day:broken -->"
        try (copied + broken).write(to: journal, atomically: true, encoding: .utf8)
        fresh.setDailyGoal(0)
        recorder.check(waitForJournal(fresh) && fresh.journalError != nil, "daily: a failed journal write is visible")
        let restored = AppModel(dataDirectory: directory.appendingPathComponent("second-mac"), syncJournalOnLaunch: false)
        recorder.check(restored.today.goal == 0 && restored.today.status(isToday: true) == "Rest day", "daily: rest-day edit recovers offline")
        try copied.write(to: journal, atomically: true, encoding: .utf8)
        restored.synchronizeJournal()
        recorder.check(waitForJournal(restored) && restored.journalError == nil, "daily: retry merges the cached edit")
        recorder.check(try MarkdownJournal.readEntries(from: journal).events.count == 5, "daily: retry appends only the missing edit")

        let zone = TimeZone(secondsFromGMT: -8 * 3600)!
        let end = ISO8601DateFormatter().date(from: "2026-11-27T08:05:00Z")!
        let acrossMidnight = FocusSession(id: UUID(), startedAt: end.addingTimeInterval(-1800),
            completedAt: end, duration: 1800, timeZone: zone)
        let days = FocusDay.history(JournalEntries(sessions: [acrossMidnight], events: [
            DailyEvent(.goal(2), at: end.addingTimeInterval(-3600), timeZone: zone),
            DailyEvent(.goal(1), at: end, timeZone: zone)
        ]))
        recorder.check(days["2026-11-26"]?.completed == 0 && days["2026-11-27"]?.status(isToday: false) == "Goal met",
                       "daily: the recorded local completion day gets a session spanning midnight")
        let tomorrow = Calendar.current.date(byAdding: .day, value: 1, to: midnight)!
        recorder.check(restored.takeDailyGoalPrompt(at: tomorrow) && !restored.takeDailyGoalPrompt(at: tomorrow),
                       "daily: the next local day prompts exactly once")
    }

    /// Every scheduled check-in leaves exactly one note, relaunches never duplicate them,
    /// stopping writes one summary, and the notes reach the Markdown journal.
    private static func testResearchMode(in directory: URL, recorder: inout Recorder) {
        let model = AppModel(dataDirectory: directory, syncJournalOnLaunch: false, playTone: { _ in })
        let store = ResearchStore(directory: directory, preview: false)
        let now = Date()
        let past = ResearchStudy(startedAt: now.addingTimeInterval(-4 * 86_400), days: 3, promptsPerDay: 4)
        store.update { $0.study = past }
        let sampler = ResearchSampler(model: model, store: store)
        sampler.evaluate(at: now)
        let expected = past.allPrompts().count
        let checkIns = { model.notes.filter { $0.kind == ResearchSampler.Kind.checkIn } }
        recorder.check(expected > 0 && checkIns().count == expected, "research: every past check-in is recorded once (\(checkIns().count)/\(expected))")
        recorder.check(checkIns().allSatisfy { $0["outcome"] == "missed" && $0["study"] == past.id.uuidString },
                       "research: check-ins while Still was not running are recorded as missed")
        let endings = { model.notes.filter { $0.kind == ResearchSampler.Kind.study && $0["event"] == "ended" } }
        recorder.check(endings().count == 1 && endings().first?["due"] == "\(expected)",
                       "research: a finished study writes one summary with its totals")

        // A relaunch with the same store and notes must not add anything.
        let reopened = ResearchSampler(model: model, store: ResearchStore(directory: directory, preview: false))
        reopened.evaluate(at: now.addingTimeInterval(60))
        recorder.check(checkIns().count == expected && endings().count == 1, "research: relaunching does not duplicate notes")
        recorder.check(reopened.study?.id == past.id, "research: the study survives a relaunch")

        // A new study can start once the old one is finished, and stopping summarizes it.
        reopened.clear()
        recorder.check(reopened.study == nil, "research: a finished study can be cleared")
        reopened.start(at: now)
        recorder.check(reopened.status(at: now.addingTimeInterval(1)) != nil, "research: a running study reports its status")
        reopened.stop(at: now.addingTimeInterval(120))
        recorder.check(endings().count == 2 && reopened.status(at: now.addingTimeInterval(180)) == nil,
                       "research: stopping ends the study with a second summary")
        let starts = model.notes.filter { $0.kind == ResearchSampler.Kind.study && $0["event"] == "started" }
        recorder.check(starts.count == 1, "research: starting a study is recorded")

        // Notes reach the Markdown journal and come back from it.
        recorder.check(model.setJournalPath(model.preferences.journalPath), "research: the journal accepts notes")
        let journal = (try? MarkdownJournal.readEntries(from: URL(fileURLWithPath: model.preferences.journalPath)))?.notes ?? []
        recorder.check(journal.count == model.notes.count && journal.count >= expected + 3,
                       "research: every note is in the Markdown journal (\(journal.count))")
        let restored = AppModel(dataDirectory: directory, syncJournalOnLaunch: false)
        recorder.check(restored.notes.count == model.notes.count, "research: notes survive in the local recovery cache")
    }

